  `emp_name_ext` varchar(10) DEFAULT NULL,
  `emp_email` varchar(50) NOT NULL,
  `emp_dob` datetime DEFAULT NULL,
  `emp_degree_main` varchar(100) NOT NULL,
  `emp_degree_major` varchar(50) NOT NULL,
  `emp_degree_minor` varchar(50) NOT NULL,
  `emp_degree_ext` varchar(50) NOT NULL,
  `emp_designation` varchar(50) NOT NULL,
  `emp_load_displacement` int(11) NOT NULL,
  `empvoid` int(1) NOT NULL,
  `emp_gender` varchar(10) NOT NULL,
  `emp_height` varchar(5) NOT NULL,
  `emp_weight` varchar(5) NOT NULL,
  `emp_blood_type` varchar(5) NOT NULL,
  `emp_civil_status` varchar(15) NOT NULL,
  `emp_rank` varchar(50) NOT NULL,
  `emp_status` varchar(15) NOT NULL,
  `emp_eligibility` varchar(100) NOT NULL,
  `emp_gsis_id` varchar(20) NOT NULL,
  `emp_pagibig_id` varchar(20) NOT NULL,
  `emp_philhealth_id` varchar(20) NOT NULL,
  `emp_sss_no` varchar(20) NOT NULL,
  `emp_tin_no` varchar(20) NOT NULL,
  `emp_employee_no` varchar(20) NOT NULL,
  `emp_residential_address` text NOT NULL,
  `emp_permanent_address` text NOT NULL,
  `emp_tel_no` varchar(20) NOT NULL,
  `emp_mobile_no` varchar(11) NOT NULL,
  `emp_spouse_name` varchar(50) NOT NULL,
  `emp_spouse_occupation` varchar(50) NOT NULL,
  `emp_spouse_employer` varchar(50) NOT NULL,
  `emp_spouse_employer_address` text NOT NULL,
  `emp_service_length` int(11) NOT NULL,
  `dateCreated` datetime DEFAULT NULL,
  `dateUpdated` datetime DEFAULT NULL,
  `dateDeleted` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

