--
-- Table structure for table `employee_educational_attainments`
--

CREATE TABLE `employee_educational_attainments` (
  `fea_id` int(11) NOT NULL,
  `empid` int(11) NOT NULL,
  `fea_degree` varchar(10) NOT NULL,
  `fea_program` varchar(100) NOT NULL,
  `fea_school` varchar(100) NOT NULL,
  `fea_specialization` varchar(100) NOT NULL,
  `fea_scholarship` varchar(100) NOT NULL,
  `fea_status` varchar(50) NOT NULL,
  `fea_earned_units` int(11) NOT NULL,
  `dateCreated` datetime NOT NULL,
  `dateUpdated` datetime NOT NULL,
  `fea_date_graduated` datetime DEFAULT '1970-01-01 00:00:00'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

