--
-- Table structure for table `faculty_evaluation`
--

CREATE TABLE `faculty_evaluation` (
  `id` int(11) NOT NULL,
  `term` enum('First','Second','Midyear','') NOT NULL,
  `academic_year` text NOT NULL,
  `faculty_name` varchar(150) DEFAULT NULL,
  `rated_by` enum('Student','Supervisor') DEFAULT NULL,
  `A1` tinyint(4) DEFAULT NULL,
  `A2` tinyint(4) DEFAULT NULL,
  `A3` tinyint(4) DEFAULT NULL,
  `A4` tinyint(4) DEFAULT NULL,
  `A5` tinyint(4) DEFAULT NULL,
  `B1` tinyint(4) DEFAULT NULL,
  `B2` tinyint(4) DEFAULT NULL,
  `B3` tinyint(4) DEFAULT NULL,
  `B4` tinyint(4) DEFAULT NULL,
  `B5` tinyint(4) DEFAULT NULL,
  `C1` tinyint(4) DEFAULT NULL,
  `C2` tinyint(4) DEFAULT NULL,
  `C3` tinyint(4) DEFAULT NULL,
  `C4` tinyint(4) DEFAULT NULL,
  `C5` tinyint(4) DEFAULT NULL,
  `D1` tinyint(4) DEFAULT NULL,
  `D2` tinyint(4) DEFAULT NULL,
  `D3` tinyint(4) DEFAULT NULL,
  `D4` tinyint(4) DEFAULT NULL,
  `D5` tinyint(4) DEFAULT NULL,
  `comments` text
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

