(512, 'First', '2025-2026', 'BUENAVIDES, JADE A.', 'Student', 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 'Okay'),
