(2633, 'First', '2025-2026', 'REMEGIO, ALEX N.', 'Student', 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 'I\'m hesitant to go to school because this teacher\'s class is all projects, no actual lessons. Attendance is mandatory, but he\'s often absent himself, and he never gives updates. It makes me unsure if it\'s even worth going. But he’s Good teacher and u can be friend'),
